// Stage 3.5 — Prepare Evidence Queries v2.0.0
// Produces six validated retrieval items while carrying large context only once.

const input = $input.first().json;

if (!input || typeof input !== "object" || Array.isArray(input)) {
  throw new Error("Prepare Evidence Queries expected one Stage 3 object.");
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function cleanString(value) {
  return typeof value === "string"
    ? value.replace(/\s+/g, " ").trim()
    : "";
}

function cleanStringArray(value) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const output = [];

  for (const item of value) {
    const cleaned = cleanString(item);
    const key = cleaned.toLowerCase();
    if (!cleaned || seen.has(key)) continue;
    seen.add(key);
    output.push(cleaned);
  }

  return output;
}

const record =
  input.opportunity_record ||
  input.job_intelligence_record ||
  input.stage_3_record ||
  input.scoring_record ||
  input;

if (!isPlainObject(record)) {
  throw new Error("Prepare Evidence Queries could not resolve the Stage 3 record.");
}

const analysis =
  input.analysis_json ||
  input.stage_2_analysis ||
  record.stage_2_analysis ||
  record.raw_job?.analysis_json ||
  null;

if (!isPlainObject(analysis)) {
  throw new Error("Prepare Evidence Queries is missing the Stage 2 analysis.");
}

const evidenceRetrieval = analysis.evidence_retrieval;

if (!isPlainObject(evidenceRetrieval)) {
  throw new Error("Prepare Evidence Queries is missing Stage 2 evidence_retrieval data.");
}

const jobIdCandidates = [
  input.job_id,
  record.job_id,
  record.raw_job?.job_id,
  analysis.job_id
]
  .map(value => cleanString(value))
  .filter(Boolean);

const uniqueJobIds = [...new Set(jobIdCandidates)];

if (uniqueJobIds.length === 0) {
  throw new Error("Prepare Evidence Queries is missing job_id.");
}

if (uniqueJobIds.length > 1) {
  throw new Error(
    `Prepare Evidence Queries found conflicting job IDs: ${uniqueJobIds.join(", ")}.`
  );
}

const jobId = uniqueJobIds[0];

const queryDefinitions = [
  ["technical", "technical_evidence_query"],
  ["capability", "capability_evidence_query"],
  ["engineering", "engineering_evidence_query"],
  ["business_problem", "business_problem_evidence_query"],
  ["similar_project", "similar_project_evidence_query"],
  ["confidence_boundary", "confidence_boundary_query"]
].map(([queryType, sourceField], index) => ({
  query_type: queryType,
  source_field: sourceField,
  query_index: index + 1,
  query_text: cleanString(evidenceRetrieval[sourceField])
}));

const missingQueries = queryDefinitions
  .filter(query => !query.query_text)
  .map(query => query.query_type);

if (missingQueries.length) {
  throw new Error(
    `Prepare Evidence Queries is missing query text for: ${missingQueries.join(", ")}.`
  );
}

const oversizedQueries = queryDefinitions
  .filter(query => query.query_text.length > 2000)
  .map(query => query.query_type);

if (oversizedQueries.length) {
  throw new Error(
    `Prepare Evidence Queries found oversized query text for: ${oversizedQueries.join(", ")}.`
  );
}

const normalizedQueryKeys = queryDefinitions.map(query =>
  query.query_text.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()
);

const duplicateQueryTypes = queryDefinitions
  .filter((query, index) => normalizedQueryKeys.indexOf(normalizedQueryKeys[index]) !== index)
  .map(query => query.query_type);

if (duplicateQueryTypes.length) {
  throw new Error(
    `Prepare Evidence Queries found duplicate queries for: ${duplicateQueryTypes.join(", ")}.`
  );
}

const evidenceRequirements = {
  required_evidence: cleanStringArray(evidenceRetrieval.required_evidence),
  direct_claims_to_verify: cleanStringArray(evidenceRetrieval.direct_claims_to_verify),
  adjacent_experience_to_check: cleanStringArray(
    evidenceRetrieval.adjacent_experience_to_check
  ),
  missing_or_risky_claims: cleanStringArray(evidenceRetrieval.missing_or_risky_claims)
};

const batchMetadata = {
  version: "2.0.0",
  query_count: queryDefinitions.length,
  query_types: queryDefinitions.map(query => query.query_type),
  job_id_verified: true,
  queries_complete: true,
  queries_unique: true,
  large_context_carried_once: true
};

return queryDefinitions.map(query => {
  const compactItem = {
    job_id: jobId,
    query_id: `${jobId}_${query.query_type}`,
    query_index: query.query_index,
    query_type: query.query_type,
    query_text: query.query_text
  };

  // Existing downstream nodes recover the original Stage 3 record from the
  // first Prepare Evidence Queries item. Carry it once rather than six times.
  if (query.query_index === 1) {
    return {
      json: {
        ...compactItem,
        evidence_requirements: evidenceRequirements,
        query_batch_metadata: batchMetadata,
        job_intelligence_record: {
          ...record,
          source_identity: input.source_identity ?? record.source_identity
        }
      }
    };
  }

  return { json: compactItem };
});

// Stage 3.5 — Normalize Retrieved Chunks v2.0.0
// n8n Code node mode: Run Once for All Items

const qdrantItems = $input.all();
const queryItems = $("Prepare Evidence Queries").all();

function fail(message) {
  throw new Error(`[Normalize Retrieved Chunks v2] ${message}`);
}

function cleanText(value) {
  return typeof value === "string"
    ? value.replace(/\r\n/g, "\n").replace(/[ \t]+/g, " ").trim()
    : "";
}

function requireText(value, label) {
  const result = cleanText(value);
  if (!result) fail(`${label} is missing or empty.`);
  return result;
}

function normalizeCategories(value) {
  if (Array.isArray(value)) {
    return [...new Set(value.map(cleanText).filter(Boolean))];
  }

  const single = cleanText(value);
  return single ? [single] : [];
}

function extractPoints(response, responseIndex) {
  const candidates = [
    response?.result?.points,
    response?.points,
    Array.isArray(response?.result) ? response.result : null,
  ];

  const points = candidates.find(Array.isArray);

  if (!points) {
    fail(`Qdrant response ${responseIndex + 1} does not contain a points array.`);
  }

  if (points.length === 0) {
    fail(`Qdrant returned zero candidates for query ${responseIndex + 1}.`);
  }

  return points;
}

if (qdrantItems.length === 0) {
  fail("No Qdrant responses were received.");
}

if (queryItems.length === 0) {
  fail('No items were found in "Prepare Evidence Queries".');
}

if (qdrantItems.length !== queryItems.length) {
  fail(
    `Query/response count mismatch: ${queryItems.length} prepared queries but ` +
    `${qdrantItems.length} Qdrant responses.`,
  );
}

const queryIds = new Set();
const queryTypes = new Set();
const normalized = [];

for (let responseIndex = 0; responseIndex < qdrantItems.length; responseIndex++) {
  const query = queryItems[responseIndex]?.json || {};
  const response = qdrantItems[responseIndex]?.json || {};

  const jobId = requireText(String(query.job_id ?? ""), `Query ${responseIndex + 1} job_id`);
  const queryId = requireText(query.query_id, `Query ${responseIndex + 1} query_id`);
  const queryType = requireText(query.query_type, `Query ${responseIndex + 1} query_type`);
  const queryText = requireText(query.query_text, `Query ${responseIndex + 1} query_text`);
  const queryIndex = Number.isInteger(query.query_index)
    ? query.query_index
    : responseIndex + 1;

  if (queryIds.has(queryId)) fail(`Duplicate query_id detected: ${queryId}.`);
  if (queryTypes.has(queryType)) fail(`Duplicate query_type detected: ${queryType}.`);
  queryIds.add(queryId);
  queryTypes.add(queryType);

  const points = extractPoints(response, responseIndex);
  const pointIds = new Set();

  points.forEach((point, pointIndex) => {
    const payload = point?.payload || {};
    const pointId = point?.id;

    if (pointId === null || pointId === undefined || pointId === "") {
      fail(`Query ${queryType}, candidate ${pointIndex + 1} has no point_id.`);
    }

    const pointKey = String(pointId);
    if (pointIds.has(pointKey)) {
      fail(`Query ${queryType} returned duplicate point_id ${pointKey}.`);
    }
    pointIds.add(pointKey);

    const score = Number(point?.score);
    if (!Number.isFinite(score)) {
      fail(`Query ${queryType}, candidate ${pointIndex + 1} has an invalid score.`);
    }

    const text = requireText(
      payload.text ?? payload.content ?? payload.chunk,
      `Query ${queryType}, candidate ${pointIndex + 1} text`,
    );

    normalized.push({
      json: {
        job_id: jobId,
        query_id: queryId,
        query_index: queryIndex,
        evidence_type: queryType,
        query_text: queryText,

        rank: pointIndex + 1,
        qdrant_score: score,
        point_id: pointId,
        candidate_key: `${queryId}:${pointKey}`,

        filename: cleanText(payload.filename) || "Unknown source",
        section_title: cleanText(payload.section_title),
        chunk_id: cleanText(String(payload.chunk_id ?? "")) || pointKey,
        document_type: cleanText(payload.document_type),
        categories: normalizeCategories(payload.categories),
        text,

        normalization_metadata: {
          version: "2.0.0",
          source_response_index: responseIndex + 1,
          candidates_in_query: points.length,
        },
      },
      pairedItem: { item: responseIndex },
    });
  });
}

if (normalized.length === 0) {
  fail("Normalization produced zero candidate chunks.");
}

return normalized;

// Stage 3.5 — Build Reranker Prompts v2.0.0
// n8n Code node mode: Run Once for All Items

const items = $input.all();

const EXPECTED_TYPES = [
  "technical",
  "capability",
  "engineering",
  "business_problem",
  "similar_project",
  "confidence_boundary",
];

const EXPECTED_CANDIDATES_PER_QUERY = 8;
const MAX_CANDIDATE_TEXT_LENGTH = 12000;
const MAX_PROMPT_LENGTH = 120000;

function fail(message) {
  throw new Error(`[Build Reranker Prompts v2] ${message}`);
}

function cleanText(value) {
  return typeof value === "string"
    ? value.replace(/\r\n/g, "\n").replace(/[ \t]+/g, " ").trim()
    : "";
}

function requireText(value, label) {
  const result = cleanText(value);
  if (!result) fail(`${label} is missing or empty.`);
  return result;
}

function finiteNumber(value, label) {
  const result = Number(value);
  if (!Number.isFinite(result)) fail(`${label} is not a finite number.`);
  return result;
}

if (items.length === 0) {
  fail("No normalized evidence chunks were received.");
}

// Group by query_id, not merely evidence_type. This prevents evidence from
// different searches being silently mixed if query types are ever reused.
const groups = new Map();

for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
  const row = items[itemIndex]?.json || {};
  const queryId = requireText(row.query_id, `Item ${itemIndex + 1} query_id`);
  const evidenceType = requireText(
    row.evidence_type,
    `Item ${itemIndex + 1} evidence_type`,
  );
  const queryText = requireText(row.query_text, `Item ${itemIndex + 1} query_text`);
  const jobId = requireText(String(row.job_id ?? ""), `Item ${itemIndex + 1} job_id`);

  if (!EXPECTED_TYPES.includes(evidenceType)) {
    fail(`Item ${itemIndex + 1} has unsupported evidence_type "${evidenceType}".`);
  }

  if (!groups.has(queryId)) {
    groups.set(queryId, {
      job_id: jobId,
      query_id: queryId,
      query_index: Number.isInteger(row.query_index) ? row.query_index : null,
      evidence_type: evidenceType,
      query_text: queryText,
      rows: [],
    });
  }

  const group = groups.get(queryId);

  if (group.job_id !== jobId) {
    fail(`Query ${queryId} contains mixed job_id values.`);
  }
  if (group.evidence_type !== evidenceType) {
    fail(`Query ${queryId} contains mixed evidence_type values.`);
  }
  if (group.query_text !== queryText) {
    fail(`Query ${queryId} contains mixed query_text values.`);
  }

  group.rows.push(row);
}

if (groups.size !== EXPECTED_TYPES.length) {
  fail(
    `Expected ${EXPECTED_TYPES.length} query groups but received ${groups.size}.`,
  );
}

const seenTypes = new Set([...groups.values()].map(group => group.evidence_type));
const missingTypes = EXPECTED_TYPES.filter(type => !seenTypes.has(type));

if (missingTypes.length > 0) {
  fail(`Missing evidence groups: ${missingTypes.join(", ")}.`);
}

function buildCandidates(group) {
  const sortedRows = [...group.rows].sort((a, b) => {
    const rankA = Number.isFinite(Number(a.rank)) ? Number(a.rank) : 999999;
    const rankB = Number.isFinite(Number(b.rank)) ? Number(b.rank) : 999999;
    return rankA - rankB;
  });

  if (sortedRows.length !== EXPECTED_CANDIDATES_PER_QUERY) {
    fail(
      `Query ${group.query_id} expected ${EXPECTED_CANDIDATES_PER_QUERY} ` +
      `candidates but received ${sortedRows.length}.`,
    );
  }

  const pointIds = new Set();
  const ranks = new Set();

  return sortedRows.map((row, index) => {
    const pointId = row.point_id;
    if (pointId === null || pointId === undefined || pointId === "") {
      fail(`Query ${group.query_id}, candidate ${index + 1} has no point_id.`);
    }

    const pointKey = String(pointId);
    if (pointIds.has(pointKey)) {
      fail(`Query ${group.query_id} contains duplicate point_id ${pointKey}.`);
    }
    pointIds.add(pointKey);

    const rank = Number(row.rank);
    if (!Number.isInteger(rank) || rank < 1) {
      fail(`Query ${group.query_id}, point ${pointKey} has invalid rank.`);
    }
    if (ranks.has(rank)) {
      fail(`Query ${group.query_id} contains duplicate rank ${rank}.`);
    }
    ranks.add(rank);

    const text = requireText(
      row.text,
      `Query ${group.query_id}, point ${pointKey} text`,
    );

    if (text.length > MAX_CANDIDATE_TEXT_LENGTH) {
      fail(
        `Query ${group.query_id}, point ${pointKey} text exceeds ` +
        `${MAX_CANDIDATE_TEXT_LENGTH} characters.`,
      );
    }

    return {
      candidate_id: index + 1,
      point_id: pointId,
      candidate_key: cleanText(row.candidate_key) || `${group.query_id}:${pointKey}`,
      retrieval_rank: rank,
      qdrant_score: finiteNumber(
        row.qdrant_score,
        `Query ${group.query_id}, point ${pointKey} qdrant_score`,
      ),
      filename: cleanText(row.filename) || "Unknown source",
      section_title: cleanText(row.section_title),
      chunk_id: cleanText(String(row.chunk_id ?? "")) || pointKey,
      document_type: cleanText(row.document_type),
      categories: Array.isArray(row.categories)
        ? [...new Set(row.categories.map(cleanText).filter(Boolean))]
        : [],
      text,
    };
  });
}

function buildPrompt(group, candidates) {
  return `
You are evaluating retrieved evidence from a Professional Knowledge Base.

EVIDENCE CATEGORY:
${group.evidence_type}

SEARCH QUERY:
${group.query_text}

TASK:
Evaluate every supplied candidate independently against this search query.
Use only the visible candidate text. Do not invent, assume, or exaggerate
experience. A retrieval score is only a search signal; it is not proof.

For every candidate return:
- candidate_id: the supplied integer, unchanged
- relevance_score: integer from 0 to 100
- evidence_strength: exactly one of EXACT, TRANSFERABLE, FOUNDATIONAL,
  BACKGROUND, IRRELEVANT
- commercial_or_project: exactly one of Commercial, Personal Project,
  School Project, Unknown
- criticality: exactly one of Essential, Important, Supporting, Optional
- safe_for_proposal: boolean
- safe_for_interview: boolean
- supported_claim: one concise claim genuinely supported by the evidence
- reason: one concise explanation

EVIDENCE-STRENGTH DEFINITIONS:
- EXACT: directly demonstrates the requested capability.
- TRANSFERABLE: demonstrates strongly transferable delivery capability.
- FOUNDATIONAL: proves useful underlying capability but not direct delivery.
- BACKGROUND: weak contextual support only.
- IRRELEVANT: does not support the query.

SAFETY RULES:
- Never label evidence Commercial unless the text explicitly proves it.
- Do not treat school or personal work as client work.
- Technology similarity alone does not prove equivalent experience.
- IRRELEVANT candidates must have relevance_score 0, empty supported_claim,
  safe_for_proposal false, and safe_for_interview false.
- Do not omit a candidate and do not create candidate IDs.
- Select best_evidence conservatively; quality is more important than quantity.

Return one valid JSON object only, with this exact top-level structure:
{
  "evidence_type": ${JSON.stringify(group.evidence_type)},
  "query_text": ${JSON.stringify(group.query_text)},
  "client_understanding": {
    "primary_problem": "",
    "required_capabilities": [],
    "optional_capabilities": [],
    "transferable_capabilities": []
  },
  "evaluated_candidates": [
    {
      "candidate_id": 1,
      "relevance_score": 0,
      "evidence_strength": "IRRELEVANT",
      "commercial_or_project": "Unknown",
      "criticality": "Optional",
      "safe_for_proposal": false,
      "safe_for_interview": false,
      "supported_claim": "",
      "reason": ""
    }
  ],
  "overall_assessment": {
    "overall_capability_coverage": 0,
    "strongest_capabilities": [],
    "missing_capabilities": [],
    "biggest_strength": "",
    "largest_risk": "",
    "recommended_story": "",
    "proposal_strategy": "",
    "confidence": 0
  },
  "honesty_check": {
    "safe_to_claim": false,
    "risk_of_overstatement": 0,
    "reason": ""
  },
  "best_evidence": [
    {
      "candidate_id": 1,
      "supported_claim": "",
      "why_selected": ""
    }
  ]
}

Before returning, verify silently that all ${candidates.length} supplied
candidate IDs appear exactly once and that the output contains no text outside
the JSON object.

CANDIDATES TO EVALUATE:
${JSON.stringify(candidates, null, 2)}
`.trim();
}

const outputs = [];

for (const expectedType of EXPECTED_TYPES) {
  const group = [...groups.values()].find(entry => entry.evidence_type === expectedType);
  if (!group) fail(`Missing group for evidence_type ${expectedType}.`);

  const candidates = buildCandidates(group);
  const prompt = buildPrompt(group, candidates);

  if (prompt.length > MAX_PROMPT_LENGTH) {
    fail(
      `Prompt for ${group.evidence_type} exceeds ${MAX_PROMPT_LENGTH} characters.`,
    );
  }

  outputs.push({
    json: {
      job_id: group.job_id,
      query_id: group.query_id,
      query_index: group.query_index,
      evidence_type: group.evidence_type,
      query_text: group.query_text,
      candidate_count_received: group.rows.length,
      candidate_count_valid: candidates.length,
      candidates,
      prompt,
      reranker_metadata: {
        version: "2.0.0",
        expected_group_count: EXPECTED_TYPES.length,
        actual_group_count: groups.size,
        expected_candidates_per_group: EXPECTED_CANDIDATES_PER_QUERY,
        taxonomy: [
          "EXACT",
          "TRANSFERABLE",
          "FOUNDATIONAL",
          "BACKGROUND",
          "IRRELEVANT",
        ],
        validation_passed: true,
      },
    },
  });
}

return outputs;

// Stage 3.5 — Parse Evaluator JSON v2.0.0
// n8n Code node mode: Run Once for All Items
//
// The LLM is advisory. Deterministic validation and claim safety are authoritative.

const modelItems = $input.all();
const sourceItems = $("Build Reranker Prompt").all();

const EXPECTED_TYPES = [
  "technical",
  "capability",
  "engineering",
  "business_problem",
  "similar_project",
  "confidence_boundary",
];

const ALLOWED_STRENGTHS = new Set([
  "EXACT",
  "TRANSFERABLE",
  "FOUNDATIONAL",
  "BACKGROUND",
  "IRRELEVANT",
]);

const ALLOWED_ORIGINS = new Set([
  "Commercial",
  "Personal Project",
  "School Project",
  "Unknown",
]);

const ALLOWED_CRITICALITY = new Set([
  "Essential",
  "Important",
  "Supporting",
  "Optional",
]);

const PROPOSAL_MIN_RELEVANCE = 60;
const INTERVIEW_MIN_RELEVANCE = 10;
const MAX_PROPOSAL_EVIDENCE = 5;
const MAX_INTERVIEW_EVIDENCE = 5;

const PROPOSAL_STRENGTHS = new Set(["EXACT", "TRANSFERABLE"]);
const INTERVIEW_STRENGTHS = new Set([
  "EXACT",
  "TRANSFERABLE",
  "FOUNDATIONAL",
  "BACKGROUND",
]);

const STRENGTH_RANK = {
  EXACT: 5,
  TRANSFERABLE: 4,
  FOUNDATIONAL: 3,
  BACKGROUND: 2,
  IRRELEVANT: 1,
};

function fail(message) {
  throw new Error(`[Parse Evaluator JSON v2] ${message}`);
}

function asString(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function normalizedText(value) {
  return asString(value).replace(/\s+/g, " ").trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueStrings(value) {
  const seen = new Set();
  const output = [];

  for (const entry of asArray(value)) {
    const text = normalizedText(entry);
    const key = text.toLowerCase();
    if (!text || seen.has(key)) continue;
    seen.add(key);
    output.push(text);
  }

  return output;
}

function clampScore(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(100, Math.round(number)));
}

function asBoolean(value) {
  if (typeof value === "boolean") return value;
  if (value === 1) return true;
  if (value === 0) return false;

  const text = asString(value).toLowerCase();
  if (["true", "yes", "1"].includes(text)) return true;
  if (["false", "no", "0"].includes(text)) return false;
  return false;
}

function normalizeStrength(value) {
  const raw = asString(value).toUpperCase();
  const aliases = {
    DIRECT: "EXACT",
    ADJACENT: "TRANSFERABLE",
    WEAK: "BACKGROUND",
  };
  const result = aliases[raw] || raw;
  return ALLOWED_STRENGTHS.has(result) ? result : "IRRELEVANT";
}

function normalizeOrigin(value) {
  const raw = asString(value);
  const aliases = {
    commercial: "Commercial",
    "client work": "Commercial",
    "personal project": "Personal Project",
    personal: "Personal Project",
    "school project": "School Project",
    school: "School Project",
    coursework: "School Project",
    unknown: "Unknown",
  };
  const result = aliases[raw.toLowerCase()] || raw;
  return ALLOWED_ORIGINS.has(result) ? result : "Unknown";
}

function normalizeCriticality(value) {
  const raw = asString(value);
  const aliases = {
    essential: "Essential",
    important: "Important",
    supporting: "Supporting",
    optional: "Optional",
  };
  const result = aliases[raw.toLowerCase()] || raw;
  return ALLOWED_CRITICALITY.has(result) ? result : "Optional";
}

function extractModelOutput(input, itemIndex) {
  const outputBlocks = Array.isArray(input?.output) ? input.output : [];
  const content = outputBlocks.flatMap(block =>
    Array.isArray(block?.content) ? block.content : [],
  );

  const outputText = content.find(entry => entry?.type === "output_text");
  const fallback = content[0];

  const value =
    outputText?.text ??
    fallback?.text ??
    input?.message?.content ??
    input?.text ??
    input?.content ??
    null;

  if (value === null || value === undefined) {
    fail(`Model item ${itemIndex + 1} contains no evaluator output.`);
  }

  return value;
}

function parseModelOutput(value, itemIndex) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value;
  }

  if (typeof value !== "string") {
    fail(`Model item ${itemIndex + 1} has unsupported output type ${typeof value}.`);
  }

  const raw = value.replace(/```json/gi, "").replace(/```/g, "").trim();
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start < 0 || end <= start) {
    fail(`Model item ${itemIndex + 1} does not contain a JSON object.`);
  }

  try {
    return JSON.parse(raw.slice(start, end + 1));
  } catch (error) {
    fail(`Model item ${itemIndex + 1} JSON parse failed: ${error.message}`);
  }
}

if (modelItems.length === 0) fail("No model responses were received.");
if (sourceItems.length === 0) fail('No items found in "Build Reranker Prompt".');

if (modelItems.length !== sourceItems.length) {
  fail(
    `Response/source count mismatch: ${modelItems.length} model responses and ` +
    `${sourceItems.length} source groups.`,
  );
}

const sourcesByType = new Map();

for (let index = 0; index < sourceItems.length; index++) {
  const source = sourceItems[index]?.json || {};
  const type = normalizedText(source.evidence_type);
  if (!EXPECTED_TYPES.includes(type)) {
    fail(`Source item ${index + 1} has unsupported evidence_type "${type}".`);
  }
  if (sourcesByType.has(type)) fail(`Duplicate source evidence_type "${type}".`);
  if (!Array.isArray(source.candidates) || source.candidates.length === 0) {
    fail(`Source group ${type} contains no candidates.`);
  }
  sourcesByType.set(type, source);
}

const parsedByType = new Map();

for (let index = 0; index < modelItems.length; index++) {
  const input = modelItems[index]?.json || {};
  const evaluation = parseModelOutput(extractModelOutput(input, index), index);
  const type = normalizedText(evaluation.evidence_type);

  if (!EXPECTED_TYPES.includes(type)) {
    fail(`Model item ${index + 1} has unsupported evidence_type "${type}".`);
  }
  if (parsedByType.has(type)) fail(`Duplicate model evidence_type "${type}".`);

  parsedByType.set(type, { evaluation, inputIndex: index });
}

const missingTypes = EXPECTED_TYPES.filter(
  type => !sourcesByType.has(type) || !parsedByType.has(type),
);
if (missingTypes.length > 0) fail(`Missing evidence types: ${missingTypes.join(", ")}.`);

function hasPositiveProductionProof(source) {
  return /\b(?:deployed|released|running|operated|used|shipped)\s+(?:\w+\s+){0,5}(?:to|in|into)?\s*production\b/i.test(source) ||
    /\bproduction[- ]ready\b/i.test(source);
}

function hasPositiveCommercialProof(source) {
  return /\b(?:paid\s+client|client\s+project|client\s+delivery|commercial\s+project|contracted\s+to|employed\s+(?:by|at)|delivered\s+for\s+(?:a\s+)?client)\b/i.test(source);
}

function hasPositiveDeploymentProof(source) {
  return /\b(?:deployed|released|shipped)\s+(?:the\s+|a\s+|an\s+)?(?:application|app|system|service|solution|workflow|model)\b/i.test(source) ||
    /\bdeployment\s+(?:was\s+)?(?:completed|successful|implemented)\b/i.test(source);
}

function detectClaimRisks(claim, sourceText, origin) {
  const claimText = normalizedText(claim);
  const source = normalizedText(sourceText);
  const risks = [];

  if (!claimText) return ["empty_supported_claim"];

  if (/\bproduction(?:[- ]ready)?\b/i.test(claimText) && !hasPositiveProductionProof(source)) {
    risks.push("unsupported_production_claim");
  }

  if (/\b(?:commercial|paid|client work|client-delivered|professional experience)\b/i.test(claimText) &&
      (origin !== "Commercial" || !hasPositiveCommercialProof(source))) {
    risks.push("unsupported_commercial_claim");
  }

  if (/\b(?:deployed|deployment|shipped|released)\b/i.test(claimText) &&
      !hasPositiveDeploymentProof(source)) {
    risks.push("unsupported_deployment_claim");
  }

  if (/\b(?:expert|expertise|specialist|advanced|architect)\b/i.test(claimText)) {
    risks.push("unsupported_seniority_claim");
  }

  if (/\b(?:enterprise|scalable|high[- ]availability|fault[- ]tolerant|production-grade)\b/i.test(claimText)) {
    risks.push("unsupported_scale_or_maturity_claim");
  }

  if (/\b(?:secure|secured|hardened|gdpr[- ]compliant|compliant|compliance)\b/i.test(claimText)) {
    risks.push("unsupported_security_or_compliance_claim");
  }

  if (/\b(?:real users|user adoption|measurable impact|increased revenue|reduced costs?|saved \d+|improved .* by \d+%)\b/i.test(claimText)) {
    risks.push("unsupported_user_or_outcome_claim");
  }

  if (/\b(?:cross[- ]platform installer|packaged executable|installer package)\b/i.test(claimText) &&
      !/\b(?:built|created|packaged|produced)\s+(?:a\s+)?(?:cross[- ]platform\s+)?(?:installer|executable|package)\b/i.test(source)) {
    risks.push("unsupported_packaging_claim");
  }

  const sourceHasNegativeBoundary = /\b(?:claims? intentionally avoided|avoid claiming|unsupported claims?|not yet verified|not demonstrated|not supported|limitations?|confidence boundaries?|missing capabilities?)\b/i.test(source);
  const sourceLooksFragmentary = /^[a-z]|^[^A-Za-z0-9]*\w{1,3}\.|\b(?:engineer|expert|specialist|architect)\.\s*(?:conclusion|summary)\b/i.test(source);

  if (sourceHasNegativeBoundary && /\b(?:production|commercial|expert|specialist|architect|advanced|deployed|secure|scalable)\b/i.test(claimText)) {
    risks.push("negative_context_claim");
  }

  if (sourceLooksFragmentary && /\b(?:production|commercial|expert|specialist|architect|advanced|deployed|secure|scalable)\b/i.test(claimText)) {
    risks.push("fragment_context_claim");
  }

  return [...new Set(risks)];
}

function compareEvidence(a, b) {
  const strength = (STRENGTH_RANK[b.evidence_strength] || 0) -
    (STRENGTH_RANK[a.evidence_strength] || 0);
  if (strength !== 0) return strength;

  const relevance = b.relevance_score - a.relevance_score;
  if (relevance !== 0) return relevance;

  const qdrant = Number(b.qdrant_score || 0) - Number(a.qdrant_score || 0);
  if (qdrant !== 0) return qdrant;

  return a.candidate_id - b.candidate_id;
}

function deduplicateEvidence(items) {
  const seen = new Set();
  const output = [];

  for (const item of items) {
    const key = item.point_id !== null && item.point_id !== undefined
      ? String(item.point_id)
      : `${item.filename.toLowerCase()}::${item.chunk_id.toLowerCase()}::${item.supported_claim.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    output.push(item);
  }

  return output;
}

function normalizeGroup(type, source, evaluation) {
  const candidates = source.candidates;
  const originalsById = new Map();

  for (const candidate of candidates) {
    const id = Number(candidate?.candidate_id);
    if (!Number.isInteger(id) || id < 1) fail(`${type} source contains invalid candidate_id.`);
    if (originalsById.has(id)) fail(`${type} source contains duplicate candidate_id ${id}.`);
    originalsById.set(id, candidate);
  }

  const modelCandidates = asArray(evaluation.evaluated_candidates);
  const modelById = new Map();
  const invalidCandidateIds = [];
  const duplicateCandidateIds = [];

  for (const item of modelCandidates) {
    const id = Number(item?.candidate_id);
    if (!Number.isInteger(id) || !originalsById.has(id)) {
      invalidCandidateIds.push(item?.candidate_id ?? null);
      continue;
    }
    if (modelById.has(id)) {
      duplicateCandidateIds.push(id);
      continue;
    }
    modelById.set(id, item);
  }

  const missingCandidateIds = [];
  const evaluatedCandidates = [];

  for (const [id, original] of originalsById.entries()) {
    const item = modelById.get(id);

    if (!item) {
      missingCandidateIds.push(id);
      evaluatedCandidates.push({
        candidate_id: id,
        relevance_score: 0,
        evidence_strength: "IRRELEVANT",
        commercial_or_project: "Unknown",
        criticality: "Optional",
        safe_for_proposal: false,
        safe_for_interview: false,
        supported_claim: "",
        reason: "Evaluator omitted this candidate; conservatively rejected.",
        point_id: original.point_id ?? null,
        candidate_key: asString(original.candidate_key),
        retrieval_rank: Number(original.retrieval_rank || id),
        filename: asString(original.filename),
        section_title: asString(original.section_title),
        chunk_id: asString(original.chunk_id),
        document_type: asString(original.document_type),
        categories: uniqueStrings(original.categories),
        qdrant_score: Number.isFinite(Number(original.qdrant_score)) ? Number(original.qdrant_score) : 0,
        text: asString(original.text),
        claim_risk_flags: ["missing_model_evaluation"],
        deterministic_eligibility: { proposal: false, interview: false },
      });
      continue;
    }

    let strength = normalizeStrength(item.evidence_strength);
    let relevance = clampScore(item.relevance_score);
    let supportedClaim = normalizedText(item.supported_claim);
    const origin = normalizeOrigin(item.commercial_or_project);
    const criticality = normalizeCriticality(item.criticality);

    if (strength === "IRRELEVANT") {
      relevance = 0;
      supportedClaim = "";
    }

    const claimRiskFlags = detectClaimRisks(
      supportedClaim,
      original.text,
      origin,
    );

    const proposalEligible =
      asBoolean(item.safe_for_proposal) &&
      PROPOSAL_STRENGTHS.has(strength) &&
      relevance >= PROPOSAL_MIN_RELEVANCE &&
      supportedClaim.length > 0 &&
      claimRiskFlags.length === 0;

    const interviewEligible =
      asBoolean(item.safe_for_interview) &&
      INTERVIEW_STRENGTHS.has(strength) &&
      relevance >= INTERVIEW_MIN_RELEVANCE &&
      supportedClaim.length > 0 &&
      claimRiskFlags.length === 0;

    evaluatedCandidates.push({
      candidate_id: id,
      relevance_score: relevance,
      evidence_strength: strength,
      commercial_or_project: origin,
      criticality,
      safe_for_proposal: asBoolean(item.safe_for_proposal),
      safe_for_interview: asBoolean(item.safe_for_interview),
      supported_claim: supportedClaim,
      reason: normalizedText(item.reason),
      point_id: original.point_id ?? null,
      candidate_key: asString(original.candidate_key),
      retrieval_rank: Number(original.retrieval_rank || id),
      filename: asString(original.filename),
      section_title: asString(original.section_title),
      chunk_id: asString(original.chunk_id),
      document_type: asString(original.document_type),
      categories: uniqueStrings(original.categories),
      qdrant_score: Number.isFinite(Number(original.qdrant_score)) ? Number(original.qdrant_score) : 0,
      text: asString(original.text),
      claim_risk_flags: claimRiskFlags,
      deterministic_eligibility: {
        proposal: proposalEligible,
        interview: interviewEligible,
      },
    });
  }

  const modelSelectedIds = new Set(
    asArray(evaluation.best_evidence)
      .map(item => Number(item?.candidate_id))
      .filter(id => Number.isInteger(id) && originalsById.has(id)),
  );

  function selectedFirst(a, b) {
    const selectedDifference =
      Number(modelSelectedIds.has(b.candidate_id)) -
      Number(modelSelectedIds.has(a.candidate_id));
    return selectedDifference !== 0 ? selectedDifference : compareEvidence(a, b);
  }

  const proposalEligible = evaluatedCandidates
    .filter(item => item.deterministic_eligibility.proposal)
    .sort(selectedFirst);

  const bestProposalEvidence = deduplicateEvidence(proposalEligible)
    .slice(0, MAX_PROPOSAL_EVIDENCE);

  const proposalIds = new Set(bestProposalEvidence.map(item => item.candidate_id));

  const interviewEligible = evaluatedCandidates
    .filter(item =>
      item.deterministic_eligibility.interview &&
      !proposalIds.has(item.candidate_id),
    )
    .sort(selectedFirst);

  const bestInterviewEvidence = deduplicateEvidence(interviewEligible)
    .slice(0, MAX_INTERVIEW_EVIDENCE);

  const modelSelectedButRejected = evaluatedCandidates
    .filter(item =>
      modelSelectedIds.has(item.candidate_id) &&
      !item.deterministic_eligibility.proposal,
    )
    .map(item => ({
      candidate_id: item.candidate_id,
      relevance_score: item.relevance_score,
      evidence_strength: item.evidence_strength,
      model_safe_for_proposal: item.safe_for_proposal,
      claim_risk_flags: item.claim_risk_flags,
      rejection_reasons: [
        !item.safe_for_proposal ? "model_safe_for_proposal_is_false" : null,
        item.relevance_score < PROPOSAL_MIN_RELEVANCE
          ? `relevance_below_${PROPOSAL_MIN_RELEVANCE}`
          : null,
        !PROPOSAL_STRENGTHS.has(item.evidence_strength)
          ? "strength_not_allowed_for_proposal"
          : null,
        ...item.claim_risk_flags,
      ].filter(Boolean),
    }));

  const queryTextMismatch =
    normalizedText(evaluation.query_text) !== normalizedText(source.query_text);

  const modelHonestySafe = asBoolean(evaluation.honesty_check?.safe_to_claim);

  return {
    job_id: source.job_id ?? null,
    query_id: source.query_id ?? null,
    query_index: source.query_index ?? null,
    evidence_type: type,
    query_text: source.query_text,
    client_understanding: {
      primary_problem: normalizedText(evaluation.client_understanding?.primary_problem),
      required_capabilities: uniqueStrings(evaluation.client_understanding?.required_capabilities),
      optional_capabilities: uniqueStrings(evaluation.client_understanding?.optional_capabilities),
      transferable_capabilities: uniqueStrings(evaluation.client_understanding?.transferable_capabilities),
    },
    evaluated_candidates: evaluatedCandidates,
    best_evidence: bestProposalEvidence,
    best_proposal_evidence: bestProposalEvidence,
    best_interview_evidence: bestInterviewEvidence,
    overall_assessment: {
      overall_capability_coverage: clampScore(evaluation.overall_assessment?.overall_capability_coverage),
      strongest_capabilities: uniqueStrings(evaluation.overall_assessment?.strongest_capabilities),
      missing_capabilities: uniqueStrings(evaluation.overall_assessment?.missing_capabilities),
      biggest_strength: normalizedText(evaluation.overall_assessment?.biggest_strength),
      largest_risk: normalizedText(evaluation.overall_assessment?.largest_risk),
      recommended_story: normalizedText(evaluation.overall_assessment?.recommended_story),
      proposal_strategy: normalizedText(evaluation.overall_assessment?.proposal_strategy),
      confidence: clampScore(evaluation.overall_assessment?.confidence),
    },
    honesty_check: {
      safe_to_claim: modelHonestySafe && bestProposalEvidence.length > 0,
      model_safe_to_claim: modelHonestySafe,
      risk_of_overstatement: clampScore(evaluation.honesty_check?.risk_of_overstatement),
      reason: normalizedText(evaluation.honesty_check?.reason),
    },
    selection_diagnostics: {
      parser_version: "2.0.0",
      total_original_candidates: candidates.length,
      total_model_candidates: modelCandidates.length,
      total_normalized_candidates: evaluatedCandidates.length,
      invalid_candidate_ids: invalidCandidateIds,
      duplicate_candidate_ids: duplicateCandidateIds,
      missing_candidate_ids: missingCandidateIds,
      query_text_mismatch: queryTextMismatch,
      model_selected_candidate_ids: [...modelSelectedIds],
      model_selected_but_rejected: modelSelectedButRejected,
      candidates_blocked_by_claim_safety: evaluatedCandidates
        .filter(item => item.claim_risk_flags.length > 0)
        .map(item => ({
          candidate_id: item.candidate_id,
          supported_claim: item.supported_claim,
          claim_risk_flags: item.claim_risk_flags,
        })),
      proposal_eligible_count: proposalEligible.length,
      interview_eligible_count: evaluatedCandidates
        .filter(item => item.deterministic_eligibility.interview).length,
      selected_proposal_count: bestProposalEvidence.length,
      selected_interview_count: bestInterviewEvidence.length,
      proposal_rules: {
        minimum_relevance: PROPOSAL_MIN_RELEVANCE,
        allowed_strengths: [...PROPOSAL_STRENGTHS],
        model_safe_for_proposal_required: true,
        supported_claim_required: true,
        zero_claim_risk_flags_required: true,
      },
      interview_rules: {
        minimum_relevance: INTERVIEW_MIN_RELEVANCE,
        allowed_strengths: [...INTERVIEW_STRENGTHS],
        model_safe_for_interview_required: true,
        supported_claim_required: true,
        zero_claim_risk_flags_required: true,
      },
      principle:
        "The model is advisory. Deterministic identity, completeness, eligibility, ranking, and claim-safety rules are authoritative.",
    },
  };
}

const output = [];

for (const type of EXPECTED_TYPES) {
  const source = sourcesByType.get(type);
  const parsed = parsedByType.get(type);
  const normalized = normalizeGroup(type, source, parsed.evaluation);

  output.push({
    json: normalized,
    pairedItem: { item: parsed.inputIndex },
  });
}

return output;

// Stage 3.5 — Build Final Evidence Package v2.0.0
// n8n Code node mode: Run Once for All Items

const evaluatedItems = $input.all();
const prepareItem = $("Prepare Evidence Queries").first()?.json || {};

const EXPECTED_TYPES = [
  "technical",
  "capability",
  "engineering",
  "business_problem",
  "similar_project",
  "confidence_boundary",
];

const PROPOSAL_STRENGTHS = new Set(["EXACT", "TRANSFERABLE"]);
const INTERVIEW_STRENGTHS = new Set([
  "EXACT",
  "TRANSFERABLE",
  "FOUNDATIONAL",
  "BACKGROUND",
]);

const STRENGTH_RANK = {
  EXACT: 5,
  TRANSFERABLE: 4,
  FOUNDATIONAL: 3,
  BACKGROUND: 2,
  IRRELEVANT: 1,
};

const MAX_GLOBAL_PROPOSAL_EVIDENCE = 10;
const MAX_GLOBAL_INTERVIEW_EVIDENCE = 8;
const MAX_EVIDENCE_EXCERPT_LENGTH = 900;
const MAX_CLAIMS_PER_EVIDENCE = 3;

function fail(message) {
  throw new Error(`[Build Final Evidence Package v2] ${message}`);
}

function asString(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function cleanText(value) {
  return asString(value).replace(/\s+/g, " ").trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function score(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(100, Math.round(number)));
}

function uniqueStrings(values) {
  const seen = new Set();
  const output = [];

  for (const value of asArray(values)) {
    const text = cleanText(value);
    const key = text.toLowerCase();
    if (!text || seen.has(key)) continue;
    seen.add(key);
    output.push(text);
  }

  return output;
}

function truncate(value, limit = MAX_EVIDENCE_EXCERPT_LENGTH) {
  const text = cleanText(value);
  if (text.length <= limit) return text;
  return `${text.slice(0, limit - 1).trimEnd()}…`;
}

function isObject(value) {
  return value && typeof value === "object" && !Array.isArray(value);
}

if (evaluatedItems.length === 0) {
  fail("No evaluated evidence packages were received.");
}

const originalRecord =
  prepareItem.job_intelligence_record ??
  prepareItem.stage_3_record ??
  prepareItem.scoring_record ??
  (prepareItem.raw_job && prepareItem.stage_2_analysis ? prepareItem : null);

