}

function validateSelectedEvidence(evidence, type, mode) {
  const id = Number(evidence?.candidate_id);
  const strength = cleanText(evidence?.evidence_strength).toUpperCase();
  const claim = cleanText(evidence?.supported_claim);
  const risks = asArray(evidence?.claim_risk_flags).filter(Boolean);
  const eligibility = evidence?.deterministic_eligibility || {};

  if (!Number.isInteger(id) || id < 1) {
    fail(`${type} ${mode} evidence has invalid candidate_id.`);
  }
  if (!claim) fail(`${type} ${mode} evidence candidate ${id} has no claim.`);
  if (risks.length > 0) {
    fail(`${type} ${mode} evidence candidate ${id} contains claim-risk flags.`);
  }

  if (mode === "proposal") {
    if (eligibility.proposal !== true || !PROPOSAL_STRENGTHS.has(strength)) {
      fail(`${type} candidate ${id} violates proposal evidence safety.`);
    }
  } else if (
    eligibility.interview !== true ||
    !INTERVIEW_STRENGTHS.has(strength)
  ) {
    fail(`${type} candidate ${id} violates interview evidence safety.`);
  }
}

function compactEvidence(evidence, type) {
  return {
    evidence_type: type,
    candidate_id: Number(evidence.candidate_id),
    point_id: evidence.point_id ?? null,
    filename: cleanText(evidence.filename) || "Unknown source",
    chunk_id: cleanText(evidence.chunk_id),
    document_type: cleanText(evidence.document_type),
    evidence_strength: cleanText(evidence.evidence_strength).toUpperCase(),
    relevance_score: score(evidence.relevance_score),
    qdrant_score: Number.isFinite(Number(evidence.qdrant_score))
      ? Number(evidence.qdrant_score)
      : 0,
    commercial_or_project: cleanText(evidence.commercial_or_project) || "Unknown",
    criticality: cleanText(evidence.criticality) || "Optional",
    supported_claim: cleanText(evidence.supported_claim),
    reason: cleanText(evidence.reason),
    evidence_excerpt: truncate(evidence.text),
  };
}

function evidenceKey(evidence) {
  if (evidence.point_id !== null && evidence.point_id !== undefined) {
    return `point:${String(evidence.point_id)}`;
  }

  return [
    "fallback",
    evidence.filename.toLowerCase(),
    evidence.chunk_id.toLowerCase(),
  ].join(":");
}

function mergeEvidence(targetMap, evidence, type) {
  const compact = compactEvidence(evidence, type);
  const key = evidenceKey(compact);

  if (!targetMap.has(key)) {
    targetMap.set(key, {
      ...compact,
      evidence_types: [type],
      supported_claims: [compact.supported_claim],
    });
    return;
  }

  const existing = targetMap.get(key);
  existing.evidence_types = uniqueStrings([...existing.evidence_types, type]);
  existing.supported_claims = uniqueStrings([
    ...existing.supported_claims,
    compact.supported_claim,
  ]).slice(0, MAX_CLAIMS_PER_EVIDENCE);

  const existingRank = STRENGTH_RANK[existing.evidence_strength] || 0;
  const incomingRank = STRENGTH_RANK[compact.evidence_strength] || 0;

  if (
    incomingRank > existingRank ||
    (incomingRank === existingRank &&
      compact.relevance_score > existing.relevance_score)
  ) {
    const evidenceTypes = existing.evidence_types;
    const supportedClaims = existing.supported_claims;
    Object.assign(existing, compact, { evidence_types: evidenceTypes, supported_claims: supportedClaims });
  }
}

function compareEvidence(a, b) {
  const strength = (STRENGTH_RANK[b.evidence_strength] || 0) -
    (STRENGTH_RANK[a.evidence_strength] || 0);
  if (strength !== 0) return strength;

  const relevance = b.relevance_score - a.relevance_score;
  if (relevance !== 0) return relevance;

  return Number(b.qdrant_score || 0) - Number(a.qdrant_score || 0);
}

function compactReference(evidence) {
  return {
    candidate_id: Number(evidence.candidate_id),
    point_id: evidence.point_id ?? null,
    evidence_strength: cleanText(evidence.evidence_strength).toUpperCase(),
    relevance_score: score(evidence.relevance_score),
    supported_claim: cleanText(evidence.supported_claim),
  };
}

const proposalMap = new Map();
const interviewMap = new Map();
