    validateSelectedEvidence(evidence, type, "proposal");
    mergeEvidence(proposalMap, evidence, type);
  }

  for (const evidence of interviewEvidence) {
    validateSelectedEvidence(evidence, type, "interview");
    mergeEvidence(interviewMap, evidence, type);
  }

  for (const blocked of asArray(diagnostics.candidates_blocked_by_claim_safety)) {
    const claim = cleanText(blocked?.supported_claim);
    const flags = uniqueStrings(blocked?.claim_risk_flags);
    if (!claim && flags.length === 0) continue;

    blockedClaims.push({
      evidence_type: type,
      candidate_id: Number(blocked?.candidate_id) || null,
      supported_claim: claim,
      claim_risk_flags: flags,
    });
  }

  const strongest = uniqueStrings(assessment.strongest_capabilities);
  const missing = uniqueStrings(assessment.missing_capabilities);

  for (const capability of strongest) {
    const key = capability.toLowerCase();
    if (seenStrongest.has(key)) continue;
    seenStrongest.add(key);
    strongestAll.push(capability);
  }

  for (const capability of missing) {
    const key = capability.toLowerCase();
    if (seenMissing.has(key)) continue;
    seenMissing.add(key);
    missingAll.push(capability);
  }

  const coverage = score(assessment.overall_capability_coverage);
  const confidence = score(assessment.confidence);
  const overstatementRisk = score(honesty.risk_of_overstatement);
  const categorySafe = honesty.safe_to_claim === true;

  coverageTotal += coverage;
  confidenceTotal += confidence;
  highestRisk = Math.max(highestRisk, overstatementRisk);
  totalCandidatesEvaluated += Number(diagnostics.total_normalized_candidates || 0);
  if (categorySafe) safeCategoryCount += 1;
  if (!categorySafe) categorySafeForAll = false;

  categoryPacks[type] = {
    evidence_type: type,
    query_text: cleanText(pack.query_text),
    overall_capability_coverage: coverage,
    confidence,
    honesty_check: {
      safe_to_claim: categorySafe,
      risk_of_overstatement: overstatementRisk,
      reason: cleanText(honesty.reason),
    },
    strongest_capabilities: strongest,
    missing_capabilities: missing,
    biggest_strength: cleanText(assessment.biggest_strength),
    largest_risk: cleanText(assessment.largest_risk),
    recommended_story: cleanText(assessment.recommended_story),
    proposal_strategy: cleanText(assessment.proposal_strategy),
    best_evidence: proposalEvidence.map(compactReference),
    best_interview_evidence: interviewEvidence.map(compactReference),
    selection_summary: {
      candidates_evaluated: Number(diagnostics.total_normalized_candidates || 0),
      proposal_eligible_count: Number(diagnostics.proposal_eligible_count || 0),
      interview_eligible_count: Number(diagnostics.interview_eligible_count || 0),
      selected_proposal_count: proposalEvidence.length,
      selected_interview_count: interviewEvidence.length,
      blocked_claim_count: asArray(
        diagnostics.candidates_blocked_by_claim_safety,
      ).length,
    },
  };
}

let bestProposalEvidenceAll = [...proposalMap.values()].sort(compareEvidence);
let bestInterviewEvidenceAll = [...interviewMap.values()].sort(compareEvidence);

const proposalPointKeys = new Set(bestProposalEvidenceAll.map(evidenceKey));
bestInterviewEvidenceAll = bestInterviewEvidenceAll.filter(
  evidence => !proposalPointKeys.has(evidenceKey(evidence)),
);

bestProposalEvidenceAll = bestProposalEvidenceAll.slice(
  0,
  MAX_GLOBAL_PROPOSAL_EVIDENCE,
);
bestInterviewEvidenceAll = bestInterviewEvidenceAll.slice(
  0,
  MAX_GLOBAL_INTERVIEW_EVIDENCE,
);

const categoriesWithoutProposalEvidence = EXPECTED_TYPES.filter(
  type => categoryPacks[type].best_evidence.length === 0,
);

const evidencePacks = {
  schema_version: "2.0.0",

  ...categoryPacks,

  best_evidence_all: bestProposalEvidenceAll,
  best_interview_evidence_all: bestInterviewEvidenceAll,

  strongest_capabilities_all: strongestAll,
  missing_capabilities_all: missingAll,

  blocked_claims: blockedClaims,
  must_not_claim_all: uniqueStrings(
    blockedClaims.map(entry => entry.supported_claim),
  ),

  summary: {
    categories_processed: EXPECTED_TYPES.length,
    total_candidates_evaluated: totalCandidatesEvaluated,
    average_coverage: Math.round(coverageTotal / EXPECTED_TYPES.length),
    average_confidence: Math.round(confidenceTotal / EXPECTED_TYPES.length),
    highest_overstatement_risk: highestRisk,
    safe_category_count: safeCategoryCount,
    unsafe_category_count: EXPECTED_TYPES.length - safeCategoryCount,
    all_safe_to_claim: categorySafeForAll,
    any_safe_to_claim: safeCategoryCount > 0,
    all_selected_claims_safe: true,
    selected_proposal_evidence_count: bestProposalEvidenceAll.length,
    selected_interview_evidence_count: bestInterviewEvidenceAll.length,
    blocked_claim_count: blockedClaims.length,
    categories_without_proposal_evidence: categoriesWithoutProposalEvidence,
  },

  processing_metadata: {
    package_version: "2.0.0",
    source_parser_version: "2.0.0",
    full_candidate_audit_forwarded: false,
    evidence_deduplicated_by_source: true,
    generated_at: new Date().toISOString(),
  },
};

return [
  {
    json: {
      job_id: originalJobId,
      source_identity: originalRecord.source_identity,
      stage_3_5_version: "2.0.0",
      job_intelligence_record: originalRecord,
      evidence_packs: evidencePacks,
    },
  },
];

